begin;
create table if not exists public.integration_connections(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,restaurant_id uuid references public.restaurants(id) on delete cascade,provider text not null,category text not null check(category in('pos','reservations','delivery','accounting','payments','other')),display_name text not null,status text not null default 'disconnected' check(status in('disconnected','pending','connected','error','paused')),config jsonb not null default '{}'::jsonb,secret_reference text,last_sync_at timestamptz,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,restaurant_id,provider));
create table if not exists public.integration_sync_runs(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,integration_id uuid not null references public.integration_connections(id) on delete cascade,direction text not null default 'inbound' check(direction in('inbound','outbound','bidirectional')),resource_type text not null,status text not null default 'queued' check(status in('queued','running','success','partial','failed')),records_read integer not null default 0,records_written integer not null default 0,records_failed integer not null default 0,started_at timestamptz,finished_at timestamptz,error_message text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.webhook_endpoints(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,integration_id uuid references public.integration_connections(id) on delete cascade,name text not null,event_types text[] not null default '{}',endpoint_key uuid not null default gen_random_uuid(),active boolean not null default true,last_received_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.import_jobs(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,restaurant_id uuid references public.restaurants(id) on delete cascade,file_name text not null,import_type text not null,status text not null default 'pending' check(status in('pending','validating','ready','importing','completed','failed')),total_rows integer not null default 0,success_rows integer not null default 0,error_rows integer not null default 0,error_report_path text,created_at timestamptz not null default now(),completed_at timestamptz);
create index if not exists integrations_company_idx on public.integration_connections(company_id,category,status);create index if not exists sync_runs_integration_idx on public.integration_sync_runs(integration_id,created_at desc);create index if not exists imports_company_idx on public.import_jobs(company_id,status,created_at desc);
alter table public.integration_connections enable row level security;alter table public.integration_sync_runs enable row level security;alter table public.webhook_endpoints enable row level security;alter table public.import_jobs enable row level security;
do $$ declare t text;begin foreach t in array array['integration_connections','integration_sync_runs','webhook_endpoints','import_jobs'] loop execute format('drop policy if exists company_members_access on public.%I',t);execute format('create policy company_members_access on public.%I for all to authenticated using(exists(select 1 from public.company_members cm where cm.company_id=%I.company_id and cm.user_id=auth.uid())) with check(exists(select 1 from public.company_members cm where cm.company_id=%I.company_id and cm.user_id=auth.uid()))',t,t,t);end loop;end $$;
grant select,insert,update,delete on public.integration_connections,public.integration_sync_runs,public.webhook_endpoints,public.import_jobs to authenticated;
do $$ declare c uuid;r uuid;pos uuid;begin select id into c from public.companies order by created_at limit 1;select id into r from public.restaurants where company_id=c order by created_at limit 1;if c is not null and r is not null then insert into public.integration_connections(company_id,restaurant_id,provider,category,display_name,status,config,last_sync_at) values(c,r,'generic_pos','pos','TPV del restaurante','connected','{"sync_sales":true,"frequency":"daily"}',now()-interval '2 hours'),(c,r,'thefork','reservations','TheFork','disconnected','{}',null),(c,r,'holded','accounting','Holded','pending','{"sync_invoices":true}',null) on conflict(company_id,restaurant_id,provider) do update set display_name=excluded.display_name;select id into pos from public.integration_connections where company_id=c and restaurant_id=r and provider='generic_pos' limit 1;insert into public.integration_sync_runs(company_id,integration_id,direction,resource_type,status,records_read,records_written,started_at,finished_at) select c,pos,'inbound','sales','success',48,48,now()-interval '2 hours',now()-interval '119 minutes' where not exists(select 1 from public.integration_sync_runs where integration_id=pos);end if;end $$;
commit;
